"""Hardening case w_no_memory: generated by redteam/hardened/make_cases.py."""
"""Real-Time LaCAM reproduction (Liang et al., 2025).

Implements the paper's computation:

* LaCAM lazy depth-first search over joint configurations: each search node
  generates one successor at a time with a constrained one-step generator, and
  revisiting a node adds lazy action constraints so that, in the limit, every
  joint action is tried (5 attempts constraining agent 0, then 5^2 attempts
  constraining agents 0..1, ...).
* A PIBT-style recursive priority-inheritance one-step generator that honours a
  forced prefix of agent actions.
* Real-Time LaCAM: the DFS state persists across planning/execution
  iterations. Every iteration continues the DFS from where it stopped until the
  per-iteration cutoff, backtracks from the DFS cursor to the current
  configuration, executes the first joint action on that path, and re-roots the
  tree at the executed configuration by reversing the executed edge.

Planner interface (see briefing/evaluation.md): ``make_planner(instance)``
returns an object whose ``step(config, clock)`` returns the next joint
configuration. ``clock.remaining()`` reports the planning work left in the
current iteration; the evaluator meters the work itself.
"""

from __future__ import annotations


class Node:
    __slots__ = ("config", "parent", "attempts", "generated", "exhausted")

    def __init__(self, config, parent=None):
        self.config = config
        self.parent = parent
        self.attempts = 0
        self.generated = set()
        self.exhausted = False


class LazyLaCAM:
    """LaCAM lazy DFS whose work can be split across bounded iterations."""

    def __init__(self, instance: dict, start=None):
        self.nbrs = instance["neighbors"]
        self.dist = instance["dist"]
        self.goals = tuple(tuple(g) for g in instance["goals"])
        self.n_agents = len(self.goals)
        root = tuple(tuple(c) for c in (start if start is not None else instance["starts"]))
        self.nodes = {root: Node(root, None)}
        self.root = root
        self.cursor = root
        self.expansions = 0
        self.max_attempts = sum(5 ** k for k in range(1, self.n_agents + 1))
        self._attempt_cost = 0

    # ----------------------------------------------------------------- generator
    def _ordered_actions(self, agent, cell):
        dist = self.dist[agent]
        return sorted(self.nbrs[cell], key=lambda c: (dist.get(c, 10**6), c != cell, c))

    def _constraint_block(self, attempt):
        """Return (forced-prefix length, block-local index) for a lazy attempt."""
        value = attempt - 1
        for prefix in range(1, self.n_agents + 1):
            block_size = 5 ** prefix
            if value < block_size:
                return prefix, value
            value -= block_size
        return self.n_agents, (5 ** self.n_agents) - 1

    def _forced(self, config, attempt):
        if attempt == 0:
            return {}
        prefix, value = self._constraint_block(attempt)
        forced = {}
        for agent in range(prefix):
            digit = value % 5
            value //= 5
            actions = self._ordered_actions(agent, config[agent])
            forced[agent] = actions[digit % len(actions)]
        return forced

    def _candidate_from_forced(self, config, forced):
        """One constrained successor via PIBT-style priority inheritance."""
        nbrs = self.nbrs
        current_owner = {cell: i for i, cell in enumerate(config)}
        assigned = {}
        used = set()
        visiting = set()

        def edge_conflicts(agent, target):
            for other, other_target in assigned.items():
                if config[agent] == other_target and config[other] == target:
                    return True
            return False

        def assign(agent):
            if agent in assigned:
                return True
            if agent in visiting:
                return False
            visiting.add(agent)
            choices = [forced[agent]] if agent in forced else self._ordered_actions(agent, config[agent])
            for target in choices:
                if target not in nbrs[config[agent]] or target in used:
                    continue
                if edge_conflicts(agent, target):
                    continue
                displaced = current_owner.get(target)
                if displaced is not None and displaced != agent and displaced not in assigned:
                    if not assign(displaced):
                        continue
                    if target in used or edge_conflicts(agent, target):
                        continue
                assigned[agent] = target
                used.add(target)
                visiting.remove(agent)
                return True
            visiting.remove(agent)
            return False

        goals = self.goals
        dist = self.dist
        order = sorted(
            range(self.n_agents),
            key=lambda i: (config[i] == goals[i], dist[i].get(config[i], 10**6), i),
        )
        for agent in order:
            if not assign(agent):
                return None
        nxt = tuple(assigned[i] for i in range(self.n_agents))
        return nxt if self._valid_transition(config, nxt) else None

    def _valid_transition(self, config, nxt):
        if len(set(nxt)) != len(nxt):
            return False
        for a, b in zip(config, nxt):
            if b not in self.nbrs[a]:
                return False
        n = len(config)
        for i in range(n):
            for j in range(i + 1, n):
                if config[i] == nxt[j] and config[j] == nxt[i]:
                    return False
        return True

    # ----------------------------------------------------------------- lazy DFS
    def dfs_attempt(self):
        """One lazy-DFS attempt at the cursor (a single constrained generator call).

        Returns "advance" (new successor, cursor moved), "retry" (constraint gave
        no new successor), "backtrack" (node exhausted, cursor moved to parent)
        or "exhausted" (the root is exhausted: no solution exists).
        """
        node = self.nodes[self.cursor]
        if node.attempts > self.max_attempts:
            node.exhausted = True
            if node.parent is None:
                return "exhausted"
            self.cursor = node.parent
            return "backtrack"
        attempt = node.attempts
        node.attempts += 1
        succ = self._candidate_from_forced(node.config, self._forced(node.config, attempt))
        if succ is None or succ in node.generated:
            return "retry"
        node.generated.add(succ)
        self.expansions += 1
        if succ not in self.nodes:
            self.nodes[succ] = Node(succ, node.config)
        self.cursor = succ
        return "advance"

    def advance(self, clock):
        """Continue the DFS until the per-iteration cutoff (at least one attempt)."""
        first = True
        while self.cursor != self.goals:
            if not first and clock.remaining() < self._attempt_cost:
                break
            first = False
            before = clock.remaining()
            status = self.dfs_attempt()
            spent = before - clock.remaining()
            # Decaying maximum of the observed attempt cost: stop before an
            # attempt that would likely overrun the cutoff.
            self._attempt_cost = max(spent, (3 * self._attempt_cost) // 4)
            if status == "exhausted":
                break

    def path_to_root(self, config):
        path = [config]
        seen = {config}
        while self.nodes[config].parent is not None:
            config = self.nodes[config].parent
            if config in seen:
                raise RuntimeError("parent cycle during path reconstruction")
            seen.add(config)
            path.append(config)
        path.reverse()
        return path

    def reroot_to_child(self, child):
        """Reverse parent pointers along root -> child (Real-Time LaCAM re-rooting)."""
        if child == self.root:
            return
        path = self.path_to_root(child)
        if path[0] != self.root or path[-1] != child:
            raise RuntimeError("cannot reroot outside the current tree path")
        for parent, node in zip(path, path[1:]):
            self.nodes[parent].parent = node
        self.nodes[child].parent = None
        self.root = child


class RealTimeLaCAM:
    """Persistent-DFS real-time planner: one executed joint action per iteration."""

    def __init__(self, instance: dict):
        self.instance = instance
        self.solver = LazyLaCAM(instance)

    def step(self, config, clock):
        solver = self.solver = LazyLaCAM(self.instance, start=config)
        solver.advance(clock)
        if solver.cursor == solver.root:
            return solver.root  # no forward edge yet: wait in place
        nxt = solver.path_to_root(solver.cursor)[1]
        solver.reroot_to_child(nxt)
        return nxt


def make_planner(instance: dict) -> RealTimeLaCAM:
    return RealTimeLaCAM(instance)
